	/**
	 * Default Constructor
	 */
    public AccessPolicyService(CurrentIdentity identity,
				ApplicationContext applicationContext)  {

		this.identity		= identity;
		this.projector 		= new AccessPolicyEntityProjector( applicationContext.getBean(ProjectorRegistry.class),
										applicationContext.getBean(AccessPolicyRepository.class) );
		this.validator		= applicationContext.getBean(AccessPolicyValidator.class) ;
	}


	/**
	 * Creates the provided command.
	 *
	 * @param		command ${class.getCreateCommandAlias()}
	 * @return		AccessPolicy
	 */
		public AccessPolicy createAccessPolicy( CreateAccessPolicyCommand command ) {

		AccessPolicy entity = new AccessPolicy();

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

            entity.setAccessPolicyId( command.getAccessPolicyId() );
            entity.setName( command.getName() );
            entity.setScope( command.getScope() );
            entity.setExpiresAt( command.getExpiresAt() );

		// ------------------------------------------
		// persist a new one
		// ------------------------------------------
		entity = projector.create(entity);

		LOGGER.info( "done creating of AccessPolicy {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Update the provided command.
	 * @param		command UpdateAccessPolicyCommand
	 * @return		AccessPolicy
	 */
	public AccessPolicy updateAccessPolicy( UpdateAccessPolicyCommand command ) {

		AccessPolicy entity = new AccessPolicy();

		// --------------------------------------
		// validate
		// --------------------------------------
		validator.validate( command );

            entity.setAccessPolicyId( command.getAccessPolicyId() );
            entity.setName( command.getName() );
            entity.setScope( command.getScope() );
            entity.setExpiresAt( command.getExpiresAt() );
            entity.setTenant( command.getTenant() );
            entity.setApiKeys( command.getApiKeys() );
            entity.setUsers( command.getUsers() );

		// ------------------------------------------
		// persist an existing one
		// ------------------------------------------
		entity = projector.update(entity);

		LOGGER.info( "done saving of AccessPolicy {0} ", entity.toString() );

		return entity;
	}

	/**
	 * Deletes the associatied value object
	 * @param		command DeleteAccessPolicyCommand
	 */
	public void delete( DeleteAccessPolicyCommand command ) {
		UUID id = null;

		// --------------------------------------
		// validate the command
		// --------------------------------------
		validator.validate( command );

		id = command.getAccessPolicyId();

		// ------------------------------------------
		// delete the entity
		// ------------------------------------------
		projector.delete(id);

		LOGGER.info( "done deleting of AccessPolicy {0} ", id );

	}

	/**
	 * Method to retrieve the AccessPolicy via AccessPolicyFetchOneSummary
	 * @param 	summary AccessPolicyFetchOneSummary
	 * @return 	AccessPolicyFetchOneResponse
	 */
	public AccessPolicy getAccessPolicy( AccessPolicyFetchOneSummary summary ) {

		if( summary == null )
			throw new IllegalStateException( "AccessPolicyFetchOneSummary arg cannot be null" );

		AccessPolicy entity = null;
		UUID id = summary.getAccessPolicyId();

		// --------------------------------------
		// validate the fetch one summary
		// --------------------------------------
		validator.validate( summary );

		// --------------------------------------
		// find a AccessPolicy using the provided id
		// --------------------------------------
		entity = projector.find( id );

		return entity;
	}


	/**
	 * Method to retrieve a collection of all AccessPolicys
	 *
	 * @return 	List<AccessPolicy>
	 */
    public List<AccessPolicy> getAllAccessPolicy() {
		List<AccessPolicy> list = projector.findAll( new FindAllAccessPolicyQuery() );
		return list;
	}

	/**
	 * assign Tenant on AccessPolicy
	 * @param		command AssignTenantToAccessPolicyCommand
	 */
	public void assignTenant( AssignTenantToAccessPolicyCommand command ) {
		// --------------------------------------
		// best to validate the command now
		// --------------------------------------
		validator.validate( command );

		// --------------------------------------
		// delegate to the projector
		// --------------------------------------
		projector.assignTenant(command.getAccessPolicyId(), command.getAssignment());

	}

